function decodeUnicodeEscapes(text) {
  if (typeof text !== 'string') return text;
  let prev = null;
  let cur = text;
  const reBackslashU = /\\u([0-9a-fA-F]{4})/g;
  const reDoubleBackslashU = /\\u([0-9a-fA-F]{4})/g;
  const reBareU = /(^|[^0-9a-fA-F])u([0-9a-fA-F]{4})/g;

  while (prev !== cur) {
    prev = cur;
    cur = cur.replace(reDoubleBackslashU, (_, hex) => String.fromCharCode(parseInt(hex, 16)));
    cur = cur.replace(reBackslashU, (_, hex) => String.fromCharCode(parseInt(hex, 16)));
    cur = cur.replace(reBareU, (m, p, hex) => p + String.fromCharCode(parseInt(hex, 16)));
  }
  return cur;
}

function normalizeQuestionsData(data) {
  if (!data || !data.sections) return data;
  data.subject = decodeUnicodeEscapes(data.subject);
  data.sections.forEach(section => {
    section.title = decodeUnicodeEscapes(section.title);
    section.questions.forEach(q => {
      q.text = decodeUnicodeEscapes(q.text);
      if (Array.isArray(q.options)) {
        q.options.forEach(o => { o.text = decodeUnicodeEscapes(o.text); });
      }
    });
  });
  return data;
}

