TEXT.welcome_prefix = 'Welcome, Engineer';

function shuffle(items) {
  const result = [...items];
  for (let i = result.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [result[i], result[j]] = [result[j], result[i]];
  }
  return result;
}

function progressKey() {
  return `smartQuizProgress:${state.user?.academicId || 'guest'}`;
}

function loadProgress() {
  try { return JSON.parse(localStorage.getItem(progressKey())) || { subjects: {}, mistakes: [] }; }
  catch (_) { return { subjects: {}, mistakes: [] }; }
}

function saveProgress(progress) {
  localStorage.setItem(progressKey(), JSON.stringify(progress));
}

function questionKey(q) {
  return `${state.currentSubject?.id || 'subject'}:${q.id}`;
}

const toastEl = document.getElementById('toast');
const userChip = document.getElementById('userChip');

const SURVEY_URL = 'https://docs.google.com/forms/d/e/1FAIpQLSdplJT6OWm7BAPumjwU-J034pgQc_G2uq488MeFX8vY3xmJUw/viewform?usp=publish-editor';
const SURVEY_KEY = 'smartQuizSurveyDone';

function setupSurveyGate() {
  const frame = document.getElementById('surveyFrame');
  const check = document.getElementById('surveyDoneCheck');
  const btn = document.getElementById('surveyDoneBtn');
  if (!frame || !check || !btn) return false;

  const isDone = localStorage.getItem(SURVEY_KEY) === '1';
  frame.src = SURVEY_URL;
  btn.disabled = true;

  if (!isDone) showScreen('survey');

  check.addEventListener('change', () => {
    btn.disabled = !check.checked;
  });

  btn.addEventListener('click', () => {
    if (!check.checked) return;
    localStorage.setItem(SURVEY_KEY, '1');
    showScreen(state.user ? 'home' : 'login');
  });
  return !isDone;
}

function showToast(message) {
  toastEl.textContent = message;
  toastEl.hidden = false;
  setTimeout(() => { toastEl.hidden = true; }, 2200);
}


function goHome() {
  stopTimer();
  state.currentIndex = 0;
  state.questions = [];
  state.answers = [];
  state.currentSection = null;
  state.currentSubject = null;
  state.currentLevel = null;
  state.currentTerm = null;
  state.data = null;
  state.searchQuery = '';
  renderHome();
  showScreen('home');
}

function showScreen(name) {
  Object.values(screens).forEach(s => s.hidden = true);
  screens[name].hidden = false;
  const globalBtn = document.getElementById('globalHomeBtn');
  if (globalBtn) globalBtn.hidden = (name === 'login' || name === 'survey');
}

function formatTime(seconds) {
  const m = Math.floor(seconds / 60).toString().padStart(2, '0');
  const s = Math.floor(seconds % 60).toString().padStart(2, '0');
  return `${m}:${s}`;
}

function updateTimer() {
  if (!state.startTime) return;
  state.elapsed = Math.floor((Date.now() - state.startTime) / 1000);
  document.getElementById('timer').textContent = formatTime(state.elapsed);
}

function startTimer() {
  clearInterval(state.timerId);
  state.startTime = Date.now();
  state.elapsed = 0;
  updateTimer();
  state.timerId = setInterval(updateTimer, 1000);
}

function stopTimer() {
  clearInterval(state.timerId);
  state.timerId = null;
}

function loadUser() {
  const raw = sessionStorage.getItem('smartQuizUser');
  if (raw) {
    state.user = JSON.parse(raw);
  }
}

function saveUser(user) {
  state.user = user;
  sessionStorage.setItem('smartQuizUser', JSON.stringify(user));
}

function renderUserChip() {
  if (!state.user) return;
  userChip.hidden = false;
  userChip.textContent = `${state.user.name} | ${state.user.academicId}`;
}

function createNavigationCard(titleText, detailText, buttonText, onClick) {
  const card = document.createElement('div');
  card.className = 'card-item';
  const title = document.createElement('h4');
  title.textContent = titleText;
  const detail = document.createElement('div');
  detail.className = 'count';
  detail.textContent = detailText;
  const button = document.createElement('button');
  button.className = 'btn primary';
  button.textContent = buttonText;
  button.addEventListener('click', onClick);
  card.append(title, detail, button);
  return card;
}

function renderLevelPicker(grid, sectionSearch) {
  if (sectionSearch) sectionSearch.hidden = true;
  document.getElementById('welcomeText').textContent = `${TEXT.welcome_prefix} ${state.user.name}`;
  document.getElementById('welcomeSub').textContent = '\u0627\u062e\u062a\u0631 \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u062f\u0631\u0627\u0633\u064a';
  document.getElementById('subjectTitle').textContent = '\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629';
  document.getElementById('subjectActions').innerHTML = '';
  [1, 2, 3, 4].forEach(level => {
    const subjectsCount = state.subjects.filter(subject => subject.level === level).length;
    grid.appendChild(createNavigationCard(
      `\u0627\u0644\u0645\u0633\u062a\u0648\u0649 ${level}`,
      subjectsCount ? `\u0627\u0644\u0645\u0648\u0627\u062f \u0627\u0644\u0645\u062a\u0627\u062d\u0629: ${subjectsCount}` : '\u0644\u0645 \u062a\u064f\u0636\u0641 \u0645\u0648\u0627\u062f \u0628\u0639\u062f',
      '\u0641\u062a\u062d \u0627\u0644\u0645\u0633\u062a\u0648\u0649',
      () => { state.currentLevel = level; state.currentTerm = null; renderHome(); }
    ));
  });
}

function renderTermPicker(grid, sectionSearch) {
  if (sectionSearch) sectionSearch.hidden = true;
  document.getElementById('welcomeText').textContent = `${TEXT.welcome_prefix} ${state.user.name}`;
  document.getElementById('welcomeSub').textContent = `\u0627\u0644\u0645\u0633\u062a\u0648\u0649 ${state.currentLevel}`;
  document.getElementById('subjectTitle').textContent = '\u0627\u062e\u062a\u0631 \u0627\u0644\u0641\u0635\u0644 \u0627\u0644\u062f\u0631\u0627\u0633\u064a';
  const actions = document.getElementById('subjectActions');
  actions.innerHTML = '';
  const back = document.createElement('button');
  back.className = 'btn ghost';
  back.textContent = '\u0627\u0644\u0631\u062c\u0648\u0639 \u0644\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a';
  back.addEventListener('click', () => { state.currentLevel = null; renderHome(); });
  actions.appendChild(back);
  [[1, '\u0627\u0644\u0641\u0635\u0644 \u0627\u0644\u0623\u0648\u0644'], [2, '\u0627\u0644\u0641\u0635\u0644 \u0627\u0644\u062b\u0627\u0646\u064a']].forEach(([term, label]) => {
    const count = state.subjects.filter(subject => subject.level === state.currentLevel && subject.term === term).length;
    grid.appendChild(createNavigationCard(
      label,
      count ? `\u0627\u0644\u0645\u0648\u0627\u062f \u0627\u0644\u0645\u062a\u0627\u062d\u0629: ${count}` : '\u0644\u0645 \u062a\u064f\u0636\u0641 \u0645\u0648\u0627\u062f \u0628\u0639\u062f',
      '\u0641\u062a\u062d \u0627\u0644\u0641\u0635\u0644',
      () => { state.currentTerm = term; renderHome(); }
    ));
  });
}

function renderHome() {
  const welcomeText = document.getElementById('welcomeText');
  const welcomeSub = document.getElementById('welcomeSub');
  const subjectTitle = document.getElementById('subjectTitle');
  const grid = document.getElementById('sectionsGrid');
  const sectionSearch = document.getElementById('sectionSearch');

  grid.innerHTML = '';

  if (!state.currentLevel) {
    renderLevelPicker(grid, sectionSearch);
    return;
  }

  if (!state.currentTerm) {
    renderTermPicker(grid, sectionSearch);
    return;
  }

  if (!state.currentSubject) {
    if (sectionSearch) sectionSearch.hidden = true;
    welcomeText.textContent = `${TEXT.welcome_prefix} ${state.user.name}`;
    welcomeSub.textContent = '\u0627\u062e\u062a\u0631 \u0627\u0644\u0645\u0627\u062f\u0629 \u0627\u0644\u062a\u064a \u062a\u0631\u064a\u062f \u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631 \u0641\u064a\u0647\u0627.';
    subjectTitle.textContent = '\u0627\u0644\u0645\u0648\u0627\u062f \u0627\u0644\u0645\u062a\u0627\u062d\u0629';

    const actions = document.getElementById('subjectActions');
    if (actions) {
      actions.innerHTML = '';
      const backBtn = document.createElement('button');
      backBtn.className = 'btn ghost';
      backBtn.textContent = '\u0627\u0644\u0631\u062c\u0648\u0639 \u0644\u0644\u0641\u0635\u0648\u0644';
      backBtn.addEventListener('click', () => { state.currentTerm = null; renderHome(); });
      actions.appendChild(backBtn);
    }

    const availableSubjects = state.subjects.filter(subject => subject.level === state.currentLevel && subject.term === state.currentTerm);
    availableSubjects.forEach(subject => {
      const allQuestions = subject.data.sections.flatMap(s => s.questions);
      const stats = loadProgress().subjects[subject.id];
      const card = document.createElement('div');
      card.className = 'card-item';
      card.innerHTML = `
        <h4>${subject.title}</h4>
        <div class=\"count\">${TEXT.count_questions}: ${allQuestions.length}</div>
        <div class=\"stats-line\">${stats ? `\u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0627\u062a: ${stats.attempts} | \u0627\u0644\u0625\u062a\u0642\u0627\u0646: ${Math.round((stats.correct / Math.max(stats.total, 1)) * 100)}%` : '\u0644\u0627 \u062a\u0648\u062c\u062f \u0645\u062d\u0627\u0648\u0644\u0627\u062a \u0628\u0639\u062f'}</div>
      `;

      const btn = document.createElement('button');
      btn.className = 'btn primary';
      btn.textContent = '\u0641\u062a\u062d \u0627\u0644\u0645\u0627\u062f\u0629';
      btn.addEventListener('click', () => {
        state.currentSubject = subject;
        state.data = subject.data;
        state.searchQuery = '';
        renderHome();
      });
      card.appendChild(btn);
      grid.appendChild(card);
    });
    if (!availableSubjects.length) {
      grid.appendChild(createNavigationCard(
        '\u0644\u0627 \u062a\u0648\u062c\u062f \u0645\u0648\u0627\u062f \u0628\u0639\u062f',
        '\u0633\u064a\u062a\u0645 \u0639\u0631\u0636 \u0627\u0644\u0645\u0648\u0627\u062f \u0647\u0646\u0627 \u0639\u0646\u062f \u0625\u0636\u0627\u0641\u062a\u0647\u0627.',
        '\u0627\u0644\u0631\u062c\u0648\u0639 \u0644\u0644\u0641\u0635\u0648\u0644',
        () => { state.currentTerm = null; renderHome(); }
      ));
    }
    return;
  }

  // Subject view
  if (sectionSearch) {
    sectionSearch.hidden = false;
    sectionSearch.placeholder = '\u0627\u0628\u062d\u062b \u0628\u0627\u0633\u0645 \u0627\u0644\u0645\u062d\u0627\u0636\u0631\u0629 \u0623\u0648 \u0643\u0644\u0645\u0629 \u0645\u0646 \u0627\u0644\u0633\u0624\u0627\u0644';
    sectionSearch.value = state.searchQuery;
  }
  welcomeText.textContent = `${TEXT.welcome_prefix} ${state.user.name}`;
  welcomeSub.textContent = `${TEXT.student_id}: ${state.user.academicId}`;
  subjectTitle.textContent = state.currentSubject?.title || state.data.subject;

  const actions = document.getElementById('subjectActions');
  if (actions) {
    actions.innerHTML = '';
    const backBtn = document.createElement('button');
    backBtn.className = 'btn ghost';
    backBtn.textContent = '\u0627\u0644\u0631\u062c\u0648\u0639 \u0644\u0644\u0645\u0648\u0627\u062f';
    backBtn.addEventListener('click', () => {
      state.currentSubject = null;
      state.data = null;
      state.searchQuery = '';
      renderHome();
    });
    actions.appendChild(backBtn);

    const resources = Array.isArray(state.currentSubject?.resources)
      ? state.currentSubject.resources
      : [];
    resources.forEach((resource) => {
      if (resource.download) {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'btn resource-download';
        button.textContent = resource.label;
        button.addEventListener('click', async () => {
          try {
            const res = await fetch(resource.href, { cache: 'no-store' });
            if (!res.ok) throw new Error('download failed');
            const blob = await res.blob();
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = resource.fileName || 'HCI.pdf';
            document.body.appendChild(a);
            a.click();
            a.remove();
            URL.revokeObjectURL(url);
            showToast('\u0628\u062f\u0623 \u062a\u0646\u0632\u064a\u0644 \u0627\u0644\u0645\u0644\u062e\u0635');
          } catch (_) {
            showToast('\u062a\u0639\u0630\u0631 \u0627\u0644\u062a\u0646\u0632\u064a\u0644 \u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u0648\u0636\u0639. \u0627\u0641\u062a\u062d \u0627\u0644\u0645\u0648\u0642\u0639 \u0639\u0628\u0631 http/https \u0623\u0648 \u0627\u0633\u062a\u0636\u0627\u0641\u0629.');
          }
        });
        actions.appendChild(button);
        return;
      }
      const link = document.createElement('a');
      link.className = 'btn resource-view';
      link.href = resource.href;
      link.textContent = resource.label;
      link.target = '_blank';
      link.rel = 'noopener';
      actions.appendChild(link);
    });

    const mistakesBtn = document.createElement('button');
    mistakesBtn.className = 'btn ghost';
    mistakesBtn.textContent = TRAINING.reviewMistakes;
    mistakesBtn.addEventListener('click', () => {
      const mistakes = new Set(loadProgress().mistakes || []);
      const questions = state.data.sections.flatMap(section => section.questions)
        .filter(q => mistakes.has(`${state.currentSubject.id}:${q.id}`));
      if (!questions.length) return showToast(TRAINING.noMistakes);
      startQuiz({ id: 'mistakes', title: TRAINING.reviewMistakes, questions }, { mode: 'practice', count: questions.length });
    });
    actions.appendChild(mistakesBtn);
  }

  const query = state.searchQuery.trim().toLowerCase();
  const filterSection = (section) => {
    if (!query || section.title.toLowerCase().includes(query)) return section;
    const questions = section.questions.filter(q => q.text.toLowerCase().includes(query));
    return questions.length ? { ...section, questions } : null;
  };
  const comprehensiveSection = state.data.sections
    .filter(s => s.isComprehensive)
    .map(filterSection)
    .find(Boolean);
  const lectureSections = state.data.sections
    .filter(s => !s.isComprehensive)
    .map(filterSection)
    .filter(Boolean);

  if (!comprehensiveSection && !lectureSections.length) {
    const emptyCard = document.createElement('div');
    emptyCard.className = 'card-item';
    const title = document.createElement('h4');
    title.textContent = '\u0627\u0644\u0645\u0644\u0627\u0632\u0645 \u062c\u0627\u0647\u0632\u0629';
    const detail = document.createElement('div');
    detail.className = 'count';
    detail.textContent = '\u0633\u064a\u062a\u0645 \u0625\u0638\u0647\u0627\u0631 \u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631 \u0647\u0646\u0627 \u0628\u0639\u062f \u0625\u0636\u0627\u0641\u0629 \u0628\u0646\u0643 \u0627\u0644\u0623\u0633\u0626\u0644\u0629.';
    emptyCard.append(title, detail);
    grid.appendChild(emptyCard);
    return;
  }

  if (comprehensiveSection) {
    grid.appendChild(createSectionCard(comprehensiveSection));
  } else {
    const allQuestions = lectureSections.flatMap(s => s.questions);
    const allCard = createSectionCard({
      id: 'all',
      title: TEXT.all_quiz,
      questions: allQuestions
    });
    grid.appendChild(allCard);
  }

  lectureSections.forEach(section => {
    grid.appendChild(createSectionCard(section));
  });
}

function createSectionCard(section) {
  const card = document.createElement('div');
  card.className = 'card-item';

  const title = document.createElement('h4');
  title.textContent = section.title;

  const count = document.createElement('div');
  count.className = 'count';
  count.textContent = `${TEXT.count_questions}: ${section.questions.length}`;

  const settings = document.createElement('div');
  settings.className = 'section-settings';
  const countSelect = document.createElement('select');
  [0, 10, 20, 50].filter(count => count === 0 || count < section.questions.length).forEach(countValue => {
    const option = document.createElement('option');
    option.value = String(countValue);
    option.textContent = countValue === 0 ? TRAINING.all : `${countValue} \u0633\u0624\u0627\u0644\u0627\u064b`;
    countSelect.appendChild(option);
  });
  const modeSelect = document.createElement('select');
  [['practice', TRAINING.practice], ['simulation', TRAINING.simulation]].forEach(([value, label]) => {
    const option = document.createElement('option');
    option.value = value;
    option.textContent = label;
    modeSelect.appendChild(option);
  });
  settings.append(countSelect, modeSelect);

  const btn = document.createElement('button');
  btn.className = 'btn primary';
  btn.textContent = TRAINING.start;
  btn.addEventListener('click', () => startQuiz(section, { mode: modeSelect.value, count: Number(countSelect.value) || section.questions.length }));

  card.appendChild(title);
  card.appendChild(count);
  card.appendChild(settings);
  card.appendChild(btn);
  return card;
}

function startQuiz(section, config = {}) {
  state.currentSection = section;
  state.quizConfig = { mode: config.mode || 'practice', count: config.count || section.questions.length };
  state.activeSectionId = section.id;
  state.mode = state.quizConfig.mode;
  state.markedQuestions = new Set();
  state.reviewFilter = 'all';
  state.questions = shuffle(section.questions).slice(0, config.count || section.questions.length).map(q => {
    const options = q.questionType === 'text' ? q.options : shuffle(q.options || []);
    return {
    id: q.id,
    text: q.text,
    questionType: q.questionType || 'choice',
    options,
    answerIndex: q.questionType === 'text' ? q.answerIndex : options.indexOf(q.options?.[q.answerIndex]),
    answerText: q.answerText,
    explanation: q.explanation
  };
  });
  state.answers = new Array(state.questions.length).fill(null);
  state.currentIndex = 0;
  document.getElementById('quizTitle').textContent = section.title;
  startTimer();
  renderQuestion();
  showScreen('quiz');
}

function renderQuestion() {
  const q = state.questions[state.currentIndex];
  const questionText = document.getElementById('questionText');
  questionText.textContent = q.text;

  const optionsList = document.getElementById('optionsList');
  optionsList.innerHTML = '';
  if (q.questionType === 'text') {
    const textarea = document.createElement('textarea');
    textarea.className = 'text-answer';
    textarea.rows = 6;
    textarea.placeholder = '\u0627\u0643\u062a\u0628 \u0625\u062c\u0627\u0628\u062a\u0643 \u0647\u0646\u0627...';
    textarea.value = typeof state.answers[state.currentIndex] === 'string' ? state.answers[state.currentIndex] : '';
    textarea.addEventListener('input', () => {
      state.answers[state.currentIndex] = textarea.value;
    });
    optionsList.appendChild(textarea);
  } else {
    q.options.forEach((opt, idx) => {
      const label = document.createElement('label');
      label.className = 'option' + (state.answers[state.currentIndex] === idx ? ' active' : '');

      const input = document.createElement('input');
      input.type = 'radio';
      input.name = 'option';
      input.checked = state.answers[state.currentIndex] === idx;

      const span = document.createElement('span');
      span.textContent = opt.text;

      label.appendChild(input);
      label.appendChild(span);
      label.addEventListener('click', () => {
        state.answers[state.currentIndex] = idx;
        renderQuestion();
      });

      optionsList.appendChild(label);
    });
  }

  const meta = document.getElementById('quizMeta');
  meta.textContent = `${TEXT.q_prefix} ${state.currentIndex + 1} ${TEXT.of} ${state.questions.length}`;

  const progress = document.getElementById('progressBar');
  progress.style.width = `${((state.currentIndex + 1) / state.questions.length) * 100}%`;

  document.getElementById('prevBtn').disabled = state.currentIndex === 0;
  document.getElementById('nextBtn').textContent = state.currentIndex === state.questions.length - 1 ? TEXT.finish : TEXT.next;

  const answered = state.answers.filter((answer, index) => isQuestionAnswered(state.questions[index], answer)).length;
  const status = document.getElementById('questionStatus');
  if (status) status.textContent = `${TRAINING.answeredStatus}${answered} | ${TRAINING.remainingStatus}${state.questions.length - answered}`;

  const markBtn = document.getElementById('markBtn');
  const isMarked = state.markedQuestions.has(state.currentIndex);
  if (markBtn) {
    markBtn.textContent = isMarked ? TRAINING.unmark : TRAINING.mark;
    markBtn.classList.toggle('marked', isMarked);
  }

  if (q.questionType !== 'text' && state.mode === 'practice' && state.answers[state.currentIndex] !== null) {
    const feedback = document.createElement('div');
    const correct = isAnswerCorrect(q, state.answers[state.currentIndex]);
    feedback.className = `quiz-feedback ${correct ? 'ok' : 'bad'}`;
    feedback.textContent = correct ? TRAINING.immediateCorrect : TRAINING.immediateWrong;
    if (!correct) feedback.textContent = `${TRAINING.immediateWrong}. ${getCorrectAnswerText(q)}`;
    if (q.explanation) feedback.textContent += ` ${TRAINING.explanation}${q.explanation}`;
    optionsList.appendChild(feedback);
  }
}

function normalizeAnswerText(value) {
  return String(value ?? '')
    .toLowerCase()
    .replace(/[^\u0600-\u06FFa-z0-9\s]/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function isQuestionAnswered(q, answer) {
  if (q.questionType === 'text') {
    return typeof answer === 'string' && answer.trim().length > 0;
  }
  return answer !== null && answer !== undefined;
}

function isAnswerCorrect(q, answer) {
  if (!isQuestionAnswered(q, answer)) return false;
  if (q.questionType === 'text') {
    const userText = normalizeAnswerText(answer);
    const correctText = normalizeAnswerText(q.answerText || '');
    if (!userText || !correctText) return false;
    if (userText === correctText) return true;
    if (userText.length >= 8 && userText.includes(correctText)) return true;
    if (correctText.length >= 8 && correctText.includes(userText)) return true;
    return false;
  }
  return answer === q.answerIndex;
}

function getCorrectAnswerText(q) {
  if (q.questionType === 'text') {
    return decodeUnicodeEscapes(q.answerText || '');
  }
  return decodeUnicodeEscapes(q.options?.[q.answerIndex]?.text ?? '');
}

function getUserAnswerText(q, answer, labels) {
  const notAnswered = labels?.notAnswered ?? '\u0644\u0645 \u064a\u062a\u0645 \u0627\u0644\u0625\u062c\u0627\u0628\u0629';
  if (!isQuestionAnswered(q, answer)) return notAnswered;
  if (q.questionType === 'text') {
    return decodeUnicodeEscapes(String(answer));
  }
  return decodeUnicodeEscapes(q.options?.[answer]?.text ?? String(answer));
}

function finishQuiz() {
  const pending = state.questions.filter((q, i) => !isQuestionAnswered(q, state.answers[i])).length;
  if (pending && !window.confirm(`\u0644\u062f\u064a\u0643 ${pending} \u0633\u0624\u0627\u0644 \u063a\u064a\u0631 \u0645\u062c\u0627\u0628. \u0647\u0644 \u062a\u0631\u064a\u062f \u0625\u0646\u0647\u0627\u0621 \u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631\u061f`)) return;
  stopTimer();

  let answered = 0;
  let correct = 0;
  let wrong = 0;

  state.questions.forEach((q, i) => {
    const ans = state.answers[i];
    if (isQuestionAnswered(q, ans)) {
      answered++;
      if (isAnswerCorrect(q, ans)) {
        correct++;
      } else {
        wrong++;
      }
    }
  });

  const unanswered = state.questions.length - answered;

  const summary = document.getElementById('summary');
  summary.innerHTML = '';

  const blocks = [
    { label: TEXT.time_spent, value: formatTime(state.elapsed) },
    { label: TEXT.count_questions, value: state.questions.length },
    { label: TEXT.answered, value: answered },
    { label: TEXT.correct, value: correct },
    { label: TEXT.wrong, value: wrong },
    { label: TEXT.unanswered, value: unanswered }
  ];

  blocks.forEach(b => {
    const box = document.createElement('div');
    box.className = 'box';
    box.innerHTML = `<div class=\"muted\">${b.label}</div><div class=\"value\">${b.value}</div>`;
    summary.appendChild(box);
  });

  state.lastSummary = {
    name: state.user?.name || '',
    academicId: state.user?.academicId || '',
    quizTitle: state.currentSection?.title || TEXT.all_quiz,
    total: state.questions.length,
    correct,
    wrong,
    unanswered,
    duration: formatTime(state.elapsed),
    questions: state.questions,
    userAnswers: state.answers
  };

  persistTrainingProgress(correct);

  const wrongList = state.questions
    .map((q, i) => ({ q, i, ans: state.answers[i] }))
    .filter(item => isQuestionAnswered(item.q, item.ans) && !isAnswerCorrect(item.q, item.ans))
    .map(item => item.i);
  state.wrongNav = { list: wrongList, pos: 0 };
  updateWrongButton();

  renderReview(state.questions, state.answers);
  showScreen('result');
}

function persistTrainingProgress(correct) {
  if (!state.currentSubject) return;
  const progress = loadProgress();
  const subjectStats = progress.subjects[state.currentSubject.id] || { attempts: 0, correct: 0, total: 0 };
  subjectStats.attempts += 1;
  subjectStats.correct += correct;
  subjectStats.total += state.questions.length;
  progress.subjects[state.currentSubject.id] = subjectStats;

  const mistakes = new Set(progress.mistakes || []);
  state.questions.forEach((q, index) => {
    const key = questionKey(q);
    if (isQuestionAnswered(q, state.answers[index]) && isAnswerCorrect(q, state.answers[index])) mistakes.delete(key);
    else if (isQuestionAnswered(q, state.answers[index])) mistakes.add(key);
  });
  progress.mistakes = [...mistakes];
  saveProgress(progress);
}

function updateWrongButton() {
  const btn = document.getElementById('nextWrongBtn');
  if (!btn) return;
  btn.disabled = !state.wrongNav.list.length;
}

function renderReview(questions = state.questions, userAnswers = state.answers, filter = state.reviewFilter) {
  const review = document.getElementById('review');
  review.innerHTML = '';
  renderReviewFilters();

  const LABELS = {
    correct: '\u0635\u062d\u064a\u062d',
    wrong: '\u062e\u0637\u0623',
    yourAnswer: '\u0625\u062c\u0627\u0628\u062a\u0643',
    correctAnswer: '\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629',
    notAnswered: '\u0644\u0645 \u064a\u062a\u0645 \u0627\u0644\u0625\u062c\u0627\u0628\u0629'
  };

  questions.forEach((q, idx) => {
    const chosenIndex = userAnswers[idx];
    const isCorrect = isAnswerCorrect(q, chosenIndex);
    const isAnswered = isQuestionAnswered(q, chosenIndex);
    if (filter === 'correct' && !isCorrect) return;
    if (filter === 'wrong' && (!isAnswered || isCorrect)) return;
    if (filter === 'unanswered' && isAnswered) return;
    const chosenText = getUserAnswerText(q, chosenIndex, LABELS);
    const correctText = getCorrectAnswerText(q);

    const item = document.createElement('div');
    item.className = 'review-item';
    item.id = `review-item-${idx}`;
    item.innerHTML = `
      <div class=\"review-head\">
        <span class=\"review-number\">#${q.number ?? (idx + 1)}</span>
        <span class=\"review-tag ${isCorrect ? 'ok' : 'bad'}\">${isCorrect ? LABELS.correct : LABELS.wrong}</span>
      </div>
      <div class=\"review-question\">${escapeHtml(decodeUnicodeEscapes(q.text))}</div>
      <div class=\"review-answers\">
        <div class=\"answer-line ${isCorrect ? 'ok' : 'bad'}\"><strong>${LABELS.yourAnswer}:</strong> ${escapeHtml(chosenText ?? LABELS.notAnswered)}</div>
        <div class=\"answer-line ok\"><strong>${LABELS.correctAnswer}:</strong> ${escapeHtml(correctText || '-')}</div>
      </div>
    `;
    review.appendChild(item);
  });
}

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function renderReviewFilters() {
  const container = document.getElementById('reviewFilters');
  if (!container) return;
  container.innerHTML = '';
  [['all', TRAINING.allResults], ['wrong', TRAINING.wrongResults], ['correct', TRAINING.correctResults], ['unanswered', TRAINING.unansweredResults]].forEach(([filter, label]) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = `btn ghost ${state.reviewFilter === filter ? 'active' : ''}`;
    button.textContent = label;
    button.addEventListener('click', () => {
      state.reviewFilter = filter;
      renderReview();
    });
    container.appendChild(button);
  });
}


function exportResults(summary) {
  const data = summary || state.lastSummary;
  if (!data) {
    showToast('\u0644\u0627 \u064a\u0648\u062c\u062f \u062a\u0642\u0631\u064a\u0631 \u0644\u0644\u062a\u0635\u062f\u064a\u0631');
    return;
  }

  const LABELS = {
    title: '\u062a\u0642\u0631\u064a\u0631 \u0646\u062a\u064a\u062c\u0629 \u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631',
    name: '\u0627\u0644\u0627\u0633\u0645',
    academicId: '\u0627\u0644\u0631\u0642\u0645 \u0627\u0644\u0623\u0643\u0627\u062f\u064a\u0645\u064a',
    subject: '\u0627\u0644\u0645\u0627\u062f\u0629 / \u0627\u0644\u0645\u062d\u0627\u0636\u0631\u0629',
    duration: '\u0627\u0644\u0648\u0642\u062a \u0627\u0644\u0645\u0633\u062a\u063a\u0631\u0642',
    total: '\u0627\u0644\u0625\u062c\u0645\u0627\u0644\u064a',
    correct: '\u0627\u0644\u0635\u062d\u064a\u062d',
    wrong: '\u0627\u0644\u062e\u0637\u0623',
    unanswered: '\u0644\u0645 \u064a\u062c\u0628',
    q: '\u0627\u0644\u0633\u0624\u0627\u0644',
    yourAnswer: '\u0625\u062c\u0627\u0628\u062a\u0643',
    correctAnswer: '\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629',
    status: '\u0627\u0644\u062d\u0627\u0644\u0629',
    notAnswered: '\u0644\u0645 \u064a\u062a\u0645 \u0627\u0644\u0625\u062c\u0627\u0628\u0629',
    ok: '\u0635\u062d\u064a\u062d',
    bad: '\u062e\u0637\u0623'
  };

  const { name, academicId, quizTitle, total, correct, wrong, unanswered, duration, questions, userAnswers } = data;

  const escapeHtml = (value) => String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\"/g, '&quot;')
    .replace(/'/g, '&#039;');

  const rows = questions.map((q, idx) => {
    const chosenIndex = userAnswers[idx];
    const isCorrect = isAnswerCorrect(q, chosenIndex);
    const chosenText = getUserAnswerText(q, chosenIndex, LABELS);
    const correctText = getCorrectAnswerText(q) || '-';
    return `
      <tr class="${isCorrect ? 'ok' : 'bad'}">
        <td class="center">${escapeHtml(q.number ?? (idx + 1))}</td>
        <td class="question">${escapeHtml(decodeUnicodeEscapes(q.text ?? ''))}</td>
        <td>${escapeHtml(chosenText)}</td>
        <td>${escapeHtml(correctText)}</td>
        <td class="center">${escapeHtml(isCorrect ? LABELS.ok : LABELS.bad)}</td>
      </tr>
    `;
  }).join('');

  const html = `
<!doctype html>
<html lang="ar" dir="rtl">
<head>
  <meta charset="utf-8" />
  <title>${escapeHtml(LABELS.title)}</title>
  <style>
    @font-face {
      font-family: "Cairo";
      src: url("fonts/Cairo-Regular.ttf") format("truetype");
      font-weight: normal;
      font-style: normal;
    }
    * { box-sizing: border-box; }
    body {
      font-family: "Cairo", "Tajawal", Arial, sans-serif;
      margin: 24px;
      color: #111827;
      direction: rtl;
    }
    h1 {
      font-size: 22px;
      margin: 0 0 12px 0;
    }
    .meta {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 8px 24px;
      margin-bottom: 12px;
      font-size: 13px;
    }
    .meta div { white-space: nowrap; }
    table {
      width: 100%;
      border-collapse: collapse;
      font-size: 12px;
      table-layout: fixed;
    }
    th, td {
      border: 1px solid #d8dbe5;
      padding: 8px 10px;
      vertical-align: top;
    }
    th {
      background: #e8f0ff;
      font-weight: 700;
    }
    .center { text-align: center; }
    .question { width: 46%; }
    .ok td { background: #f0fdf4; }
    .bad td { background: #fef2f2; }
    @media print {
      body { margin: 12mm; }
    }
  </style>
</head>
<body>
  <h1>${escapeHtml(LABELS.title)}</h1>
  <div class="meta">
    <div>${escapeHtml(LABELS.name)}: ${escapeHtml(name)}</div>
    <div>${escapeHtml(LABELS.academicId)}: ${escapeHtml(academicId)}</div>
    <div>${escapeHtml(LABELS.subject)}: ${escapeHtml(quizTitle)}</div>
    <div>${escapeHtml(LABELS.duration)}: ${escapeHtml(duration)}</div>
    <div>${escapeHtml(LABELS.total)}: ${escapeHtml(total)}</div>
    <div>${escapeHtml(LABELS.correct)}: ${escapeHtml(correct)}</div>
    <div>${escapeHtml(LABELS.wrong)}: ${escapeHtml(wrong)}</div>
    <div>${escapeHtml(LABELS.unanswered)}: ${escapeHtml(unanswered)}</div>
  </div>

  <table>
    <thead>
      <tr>
        <th class="center">#</th>
        <th>${escapeHtml(LABELS.q)}</th>
        <th>${escapeHtml(LABELS.yourAnswer)}</th>
        <th>${escapeHtml(LABELS.correctAnswer)}</th>
        <th class="center">${escapeHtml(LABELS.status)}</th>
      </tr>
    </thead>
    <tbody>
      ${rows}
    </tbody>
  </table>
</body>
</html>
  `;

  const win = window.open('', '_blank');
  if (!win) {
    showToast('\u062a\u0645 \u0645\u0646\u0639 \u0641\u062a\u062d \u0627\u0644\u0646\u0627\u0641\u0630\u0629');
    return;
  }
  win.document.open();
  win.document.write(html);
  win.document.close();
  win.focus();
  setTimeout(() => {
    win.print();
  }, 400);
}


// Events

document.getElementById('loginForm').addEventListener('submit', (e) => {
  e.preventDefault();
  const name = document.getElementById('nameInput').value.trim();
  const academicId = document.getElementById('idInput').value.trim();

  if (!name || !academicId) {
    showToast(TEXT.toast_login);
    return;
  }

  saveUser({ name, academicId });
  renderUserChip();
  renderHome();
  showScreen('home');
});

document.getElementById('logoutBtn').addEventListener('click', () => {
  sessionStorage.removeItem('smartQuizUser');
  state.user = null;
  userChip.hidden = true;
  showScreen('login');
});

document.getElementById('prevBtn').addEventListener('click', () => {
  if (state.currentIndex > 0) {
    state.currentIndex--;
    renderQuestion();
  }
});

document.getElementById('nextBtn').addEventListener('click', () => {
  if (state.currentIndex < state.questions.length - 1) {
    state.currentIndex++;
    renderQuestion();
  } else {
    finishQuiz();
  }
});

document.getElementById('finishBtn').addEventListener('click', () => {
  finishQuiz();
});

document.getElementById('retryBtn').addEventListener('click', () => {
  if (state.currentSection) {
    startQuiz(state.currentSection, state.quizConfig);
  }
});

document.getElementById('markBtn').addEventListener('click', () => {
  if (state.markedQuestions.has(state.currentIndex)) state.markedQuestions.delete(state.currentIndex);
  else state.markedQuestions.add(state.currentIndex);
  renderQuestion();
});

document.getElementById('sectionSearch').addEventListener('input', (event) => {
  state.searchQuery = event.target.value;
  renderHome();
});

document.getElementById('nextWrongBtn').addEventListener('click', () => {
  const list = state.wrongNav.list || [];
  if (!list.length) {
    showToast('لا توجد إجابات خاطئة');
    return;
  }
  if (state.wrongNav.pos >= list.length) {
    showToast('لا توجد أخطاء أخرى');
    return;
  }
  const idx = list[state.wrongNav.pos];
  state.wrongNav.pos += 1;
  const el = document.getElementById(`review-item-${idx}`);
  if (el) {
    el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    el.classList.add('highlight');
    setTimeout(() => el.classList.remove('highlight'), 1200);
  }
});

document.getElementById('exportBtn').addEventListener('click', () => {
  exportResults();
});

document.getElementById('homeBtn').addEventListener('click', () => {
  goHome();
});

document.getElementById('globalHomeBtn').addEventListener('click', () => {
  goHome();
});


function setGlobalHomeLabel() {
  const btn = document.getElementById('globalHomeBtn');
  if (btn) btn.textContent = 'الصفحة الرئيسية';
}

function init() {
  setGlobalHomeLabel();
  setupPdf();
  state.subjects = SUBJECTS_DATA.map(s => ({...s, data: normalizeQuestionsData(s.data)}));
  state.currentSubject = null;
  state.data = null;
  loadUser();
  const surveyBlocked = setupSurveyGate();
  if (surveyBlocked) return;
  if (state.user) {
    renderUserChip();
    renderHome();
    showScreen('home');
  } else {
    showScreen('login');
  }
}

init();
